// AUTO-GENERATED from "Business Tenancy Management Service Agreement - V0.2.txt" (V0.2) by scripts/genSalesAgreementClauses.js.
// Verbatim clause text; do not hand-edit — re-run the generator to refresh.
module.exports = [
  ["PURPOSE", "<p style=\"margin:6px 0;\">This Agreement sets out the terms under which Seventh Sky will provide Business Tenancy Management Services to assist the Client in locating, securing, leasing and managing suitable commercial premises.</p><p style=\"margin:6px 0;\">The specific services, pricing and project requirements for each engagement will be confirmed in the approved Quotation and Work Order.</p>"],
  ["TERM", "<p style=\"margin:6px 0;\">This Agreement becomes effective on the date it is signed by both Parties and continues until:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">the agreed Services have been completed;</li><li style=\"margin:2px 0;\">all payments have been made; and</li><li style=\"margin:2px 0;\">all obligations under this Agreement have been fulfilled,</li></ul><p style=\"margin:6px 0;\">unless terminated earlier in accordance with this Agreement.</p><p style=\"margin:6px 0;\">Where ongoing tenancy management services are engaged, this Agreement continues for the period specified in the approved Work Order.</p>"],
  ["SERVICES", "<p style=\"margin:6px 0;\">The Client may request one or more of the following services.</p><p style=\"margin:6px 0;\">Only the services selected in Schedule A or the approved Work Order form part of this Agreement.</p><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Business Leasing Consultation</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Initial Consultation</li><li style=\"margin:2px 0;\">☐ Business Requirement Assessment</li><li style=\"margin:2px 0;\">☐ Location Assessment</li><li style=\"margin:2px 0;\">☐ Rental Budget Assessment</li><li style=\"margin:2px 0;\">☐ Leasing Strategy Advice</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Property Search &amp; Shortlisting</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Commercial Property Search</li><li style=\"margin:2px 0;\">☐ Property Shortlisting</li><li style=\"margin:2px 0;\">☐ Market Rental Comparison</li><li style=\"margin:2px 0;\">☐ Property Suitability Assessment</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Property Inspection</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Inspection Coordination</li><li style=\"margin:2px 0;\">☐ Property Viewing</li><li style=\"margin:2px 0;\">☐ Landlord Meeting Coordination</li><li style=\"margin:2px 0;\">☐ Site Assessment</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Lease Negotiation</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Rental Negotiation</li><li style=\"margin:2px 0;\">☐ Commercial Terms Negotiation</li><li style=\"margin:2px 0;\">☐ Lease Condition Review Coordination</li><li style=\"margin:2px 0;\">☐ Incentive Negotiation Support</li></ul><p style=\"margin:6px 0;\">Documentation Coordination</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Letter of Offer Coordination</li><li style=\"margin:2px 0;\">☐ Lease Documentation Coordination</li><li style=\"margin:2px 0;\">☐ Supporting Documentation</li><li style=\"margin:2px 0;\">☐ Utility Connection Coordination</li></ul><p style=\"margin:6px 0;\">Move-In Coordination</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Key Collection Coordination</li><li style=\"margin:2px 0;\">☐ Handover Coordination</li><li style=\"margin:2px 0;\">☐ Fit-Out Coordination</li><li style=\"margin:2px 0;\">☐ Business Commencement Support</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Ongoing Tenancy Management</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Lease Renewal Coordination</li><li style=\"margin:2px 0;\">☐ Rent Review Assistance</li><li style=\"margin:2px 0;\">☐ Landlord Communication</li><li style=\"margin:2px 0;\">☐ Maintenance Coordination</li><li style=\"margin:2px 0;\">☐ Exit Coordination</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Additional Services</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Business Relocation Assistance</li><li style=\"margin:2px 0;\">☐ Expansion Property Search</li><li style=\"margin:2px 0;\">☐ Multiple Site Coordination</li><li style=\"margin:2px 0;\">☐ Other</li></ul><p style=\"margin:6px 0;\">Additional services may be included by written agreement.</p>"],
  ["PROJECT DETAILS", "<p style=\"margin:6px 0;\">The details of each engagement shall be recorded in Schedule B or the approved Work Order, including:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Client details;</li><li style=\"margin:2px 0;\">business activity;</li><li style=\"margin:2px 0;\">preferred location;</li><li style=\"margin:2px 0;\">property type;</li><li style=\"margin:2px 0;\">space requirements;</li><li style=\"margin:2px 0;\">rental budget;</li><li style=\"margin:2px 0;\">lease term preference;</li><li style=\"margin:2px 0;\">selected services;</li><li style=\"margin:2px 0;\">agreed pricing;</li><li style=\"margin:2px 0;\">project timeline; and</li><li style=\"margin:2px 0;\">special requirements.</li></ul><p style=\"margin:6px 0;\">If any inconsistency exists between this Agreement and the Work Order, the Work Order prevails for that project only.</p>"],
  ["RESPONSIBILITIES OF SEVENTH SKY", "<p style=\"margin:6px 0;\">Seventh Sky will:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">understand the Client's leasing requirements;</li><li style=\"margin:2px 0;\">search and shortlist suitable commercial premises;</li><li style=\"margin:2px 0;\">coordinate inspections;</li><li style=\"margin:2px 0;\">liaise with landlords and property agents;</li><li style=\"margin:2px 0;\">coordinate lease negotiations where authorised;</li><li style=\"margin:2px 0;\">coordinate lease documentation;</li><li style=\"margin:2px 0;\">provide regular project updates;</li><li style=\"margin:2px 0;\">coordinate move-in activities where requested; and</li><li style=\"margin:2px 0;\">use reasonable care and skill in delivering the agreed Services.</li></ul><p style=\"margin:6px 0;\">Unless otherwise agreed in writing, Seventh Sky acts as the Client's leasing consultant and project coordinator and is not the owner, landlord or leasing agent of the property.</p>"],
  ["CLIENT RESPONSIBILITIES", "<p style=\"margin:6px 0;\">The Client agrees to:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">provide accurate business and financial information relevant to the leasing requirements;</li><li style=\"margin:2px 0;\">advise Seventh Sky of any changes to their requirements;</li><li style=\"margin:2px 0;\">attend inspections or authorise representation where appropriate;</li><li style=\"margin:2px 0;\">review and approve proposed properties and lease terms;</li><li style=\"margin:2px 0;\">obtain independent legal, financial or taxation advice where required;</li><li style=\"margin:2px 0;\">pay all agreed fees in accordance with this Agreement; and</li><li style=\"margin:2px 0;\">cooperate throughout the leasing process.</li></ul><p style=\"margin:6px 0;\">The Client remains responsible for the final decision to enter into any lease agreement.</p>"],
  ["QUOTATIONS & WORK ORDERS", "<p style=\"margin:6px 0;\">Before work commences, Seventh Sky will provide a Quotation and, where applicable, a Work Order setting out:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">selected services;</li><li style=\"margin:2px 0;\">scope of work;</li><li style=\"margin:2px 0;\">estimated project timeline;</li><li style=\"margin:2px 0;\">agreed fees;</li><li style=\"margin:2px 0;\">payment schedule;</li><li style=\"margin:2px 0;\">expected deliverables; and</li><li style=\"margin:2px 0;\">any special conditions.</li></ul><p style=\"margin:6px 0;\">Services will commence once the Client accepts the Quotation or Work Order.</p><p style=\"margin:6px 0;\">Where the Client requests additional services after acceptance, a revised quotation or approved variation may be issued.</p>"],
  ["SERVICE FEES & PAYMENT", "<p style=\"margin:6px 0;\">The total project cost will be specified in the approved Quotation or Work Order.</p><p style=\"margin:6px 0;\">Project fees may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">consultation fees;</li><li style=\"margin:2px 0;\">property search and shortlisting;</li><li style=\"margin:2px 0;\">inspection coordination;</li><li style=\"margin:2px 0;\">lease negotiation services;</li><li style=\"margin:2px 0;\">tenancy management services;</li><li style=\"margin:2px 0;\">documentation coordination;</li><li style=\"margin:2px 0;\">utility connection coordination;</li><li style=\"margin:2px 0;\">project management fees;</li><li style=\"margin:2px 0;\">approved third-party service fees (where applicable); and</li><li style=\"margin:2px 0;\">any approved additional services.</li></ul><p style=\"margin:6px 0;\">The Client agrees to pay all agreed fees in accordance with the approved payment schedule.</p><p style=\"margin:6px 0;\">Government charges, stamp duty, lease registration fees, legal fees, landlord charges and utility connection fees are payable by the Client unless otherwise stated in the approved Quotation or Work Order.</p>"],
  ["PAYMENT TERMS", "<p style=\"margin:6px 0;\">Unless otherwise agreed in writing:</p><p style=\"margin:6px 0;\">One-Off Leasing Services</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Deposit upon acceptance of the Quotation or Work Order.</li></ul><p style=\"margin:6px 0;\">Progress payment (where applicable).</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Final payment upon completion of the agreed Services or execution of the lease, whichever occurs first.</li></ul><p style=\"margin:6px 0;\">Ongoing Tenancy Management Services</p><p style=\"margin:6px 0;\">Where the Client engages Seventh Sky for ongoing tenancy management, payment may be made:</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Weekly</li><li style=\"margin:2px 0;\">☐ Monthly</li><li style=\"margin:2px 0;\">☐ Quarterly</li><li style=\"margin:2px 0;\">☐ Annually</li></ul><p style=\"margin:6px 0;\">as specified in the approved Work Order.</p><p style=\"margin:6px 0;\">Invoices are payable within the period stated on the invoice.</p><p style=\"margin:6px 0;\">Late payments may result in suspension of the Services.</p>"],
  ["PROPERTY SEARCH & LEASE COORDINATION", "<p style=\"margin:6px 0;\">Seventh Sky will use reasonable efforts to identify commercial premises that meet the Client's stated requirements.</p><p style=\"margin:6px 0;\">The Client acknowledges that:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">property availability is subject to market conditions;</li><li style=\"margin:2px 0;\">landlords remain responsible for selecting tenants;</li><li style=\"margin:2px 0;\">leasing decisions remain at the discretion of the landlord or property owner;</li><li style=\"margin:2px 0;\">rental prices and lease terms are determined by the landlord unless negotiated otherwise; and</li><li style=\"margin:2px 0;\">Seventh Sky cannot guarantee that a particular property will remain available.</li></ul><p style=\"margin:6px 0;\">Where requested, Seventh Sky may coordinate:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">property inspections;</li><li style=\"margin:2px 0;\">landlord meetings;</li><li style=\"margin:2px 0;\">lease negotiations;</li><li style=\"margin:2px 0;\">documentation;</li><li style=\"margin:2px 0;\">utility connection arrangements; and</li><li style=\"margin:2px 0;\">move-in coordination.</li></ul>"],
  ["PROJECT TIMELINES", "<p style=\"margin:6px 0;\">Estimated commencement and completion dates will be provided in the approved Quotation or Work Order.</p><p style=\"margin:6px 0;\">Project timeframes may be affected by:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">property availability;</li><li style=\"margin:2px 0;\">landlord response times;</li><li style=\"margin:2px 0;\">lease negotiations;</li><li style=\"margin:2px 0;\">Client decisions;</li><li style=\"margin:2px 0;\">legal document preparation;</li><li style=\"margin:2px 0;\">government or utility processing;</li><li style=\"margin:2px 0;\">public holidays; or</li><li style=\"margin:2px 0;\">other circumstances beyond Seventh Sky's reasonable control.</li></ul><p style=\"margin:6px 0;\">Where delays occur, Seventh Sky will keep the Client reasonably informed and provide an updated estimated timeframe where reasonably practicable.</p>"],
  ["VARIATIONS & ADDITIONAL SERVICES", "<p style=\"margin:6px 0;\">A variation occurs where the Client requests work outside the approved scope of Services or where additional work becomes necessary.</p><p style=\"margin:6px 0;\">Examples include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">additional property inspections;</li><li style=\"margin:2px 0;\">additional property searches;</li><li style=\"margin:2px 0;\">lease renegotiations;</li><li style=\"margin:2px 0;\">multiple property options;</li><li style=\"margin:2px 0;\">fit-out coordination;</li><li style=\"margin:2px 0;\">relocation assistance;</li><li style=\"margin:2px 0;\">utility coordination;</li><li style=\"margin:2px 0;\">additional documentation; or</li><li style=\"margin:2px 0;\">any other Client-requested service.</li></ul><p style=\"margin:6px 0;\">Where practical, Seventh Sky will advise the Client of:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">the additional work;</li><li style=\"margin:2px 0;\">any additional charges; and</li><li style=\"margin:2px 0;\">any expected impact on the project timeline.</li></ul><p style=\"margin:6px 0;\">No variation will proceed without the Client's approval unless immediate action is reasonably necessary to protect the Client's interests.</p>"],
  ["THIRD-PARTY PROFESSIONALS", "<p style=\"margin:6px 0;\">The Client acknowledges that certain Services may involve or require coordination with third parties, including:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">landlords;</li><li style=\"margin:2px 0;\">property owners;</li><li style=\"margin:2px 0;\">real estate agencies;</li><li style=\"margin:2px 0;\">lawyers;</li><li style=\"margin:2px 0;\">architects;</li><li style=\"margin:2px 0;\">interior designers;</li><li style=\"margin:2px 0;\">contractors;</li><li style=\"margin:2px 0;\">utility providers; and</li><li style=\"margin:2px 0;\">government authorities.</li></ul><p style=\"margin:6px 0;\">Unless otherwise agreed in writing:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">those parties remain responsible for their own professional services and decisions;</li><li style=\"margin:2px 0;\">Seventh Sky does not guarantee the performance of independent third parties; and</li><li style=\"margin:2px 0;\">Seventh Sky remains responsible for coordinating the Services requested by the Client with reasonable care and skill.</li></ul>"],
  ["SERVICE COMPLETION", "<p style=\"margin:6px 0;\">The Services shall be considered completed when the agreed scope of work specified in the Quotation or Work Order has been substantially delivered.</p><p style=\"margin:6px 0;\">Depending on the selected services, completion may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">suitable properties shortlisted;</li><li style=\"margin:2px 0;\">inspections coordinated;</li><li style=\"margin:2px 0;\">lease negotiations completed;</li><li style=\"margin:2px 0;\">lease documentation coordinated;</li><li style=\"margin:2px 0;\">lease executed between the Client and the landlord;</li><li style=\"margin:2px 0;\">key handover coordinated;</li><li style=\"margin:2px 0;\">utility connections coordinated;</li><li style=\"margin:2px 0;\">move-in support completed; or</li><li style=\"margin:2px 0;\">ongoing tenancy management services delivered for the agreed service period.</li></ul><p style=\"margin:6px 0;\">Where ongoing tenancy management services are engaged, completion shall occur at the expiry of the agreed service period unless renewed by mutual agreement.</p>"],
  ["CLIENT COMPLAINTS & SERVICE ISSUES", "<p style=\"margin:6px 0;\">If the Client believes that the Services have not been delivered in accordance with the agreed scope, the Client should notify Seventh Sky as soon as reasonably practicable.</p><p style=\"margin:6px 0;\">Upon receiving a complaint, Seventh Sky will:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">acknowledge the complaint;</li><li style=\"margin:2px 0;\">investigate the matter;</li><li style=\"margin:2px 0;\">liaise with relevant parties where required;</li><li style=\"margin:2px 0;\">take reasonable steps to resolve the issue; and</li><li style=\"margin:2px 0;\">keep the Client informed of the outcome.</li></ul><p style=\"margin:6px 0;\">Where the issue arises from Seventh Sky's administrative oversight, reasonable efforts will be made to rectify the matter promptly.</p><p style=\"margin:6px 0;\">Nothing in this Agreement limits any rights available to the Client under applicable law.</p>"],
  ["LIABILITY", "<p style=\"margin:6px 0;\">To the extent permitted by the laws of Bangladesh:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Seventh Sky will provide the Services with reasonable care and skill.</li><li style=\"margin:2px 0;\">Seventh Sky is responsible only for the Services it has agreed to provide under this Agreement.</li><li style=\"margin:2px 0;\">Landlords remain responsible for their properties, lease terms and leasing decisions.</li></ul><p style=\"margin:6px 0;\">Real estate agencies, legal advisers, contractors and other independent professionals remain responsible for their own services.</p><p style=\"margin:6px 0;\">Neither Party shall be liable for delays or failures caused by circumstances beyond their reasonable control.</p>"],
  ["LIMITATION OF LIABILITY", "<p style=\"margin:6px 0;\">Except where liability cannot legally be excluded or limited, Seventh Sky shall not be liable for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">a landlord's decision not to lease a property to the Client;</li><li style=\"margin:2px 0;\">changes to rental prices or lease conditions made by the landlord;</li><li style=\"margin:2px 0;\">withdrawal of a property from the market;</li><li style=\"margin:2px 0;\">inaccurate or incomplete information supplied by landlords, agents or the Client;</li><li style=\"margin:2px 0;\">delays caused by third parties;</li><li style=\"margin:2px 0;\">business interruption;</li><li style=\"margin:2px 0;\">loss of business opportunity, profit or goodwill; or</li><li style=\"margin:2px 0;\">events beyond Seventh Sky's reasonable control.</li></ul><p style=\"margin:6px 0;\">Where permitted by law, Seventh Sky's total liability arising from a project shall not exceed the amount paid by the Client for the affected Services.</p><p style=\"margin:6px 0;\">This clause does not exclude liability arising from fraud, wilful misconduct or any liability that cannot legally be excluded.</p>"],
  ["CONFIDENTIALITY & PRIVACY", "<p style=\"margin:6px 0;\">Each Party agrees to keep confidential all non-public information obtained through this Agreement.</p><p style=\"margin:6px 0;\">Personal and commercial information will only be collected, used and disclosed for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">providing the requested Services;</li><li style=\"margin:2px 0;\">communicating with the Client;</li><li style=\"margin:2px 0;\">coordinating with landlords, property agents and authorised third parties;</li><li style=\"margin:2px 0;\">preparing quotations, Work Orders and invoices;</li><li style=\"margin:2px 0;\">complying with legal obligations; or</li><li style=\"margin:2px 0;\">other purposes authorised by the Client.</li></ul><p style=\"margin:6px 0;\">Neither Party shall disclose confidential information to any third party without prior consent unless required by law.</p><p style=\"margin:6px 0;\">These obligations continue after completion or termination of this Agreement.</p>"],
  ["FORCE MAJEURE", "<p style=\"margin:6px 0;\">Neither Party shall be responsible for delays or failure to perform caused by circumstances beyond its reasonable control, including:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">natural disasters;</li><li style=\"margin:2px 0;\">severe weather;</li><li style=\"margin:2px 0;\">government restrictions;</li><li style=\"margin:2px 0;\">industrial action;</li><li style=\"margin:2px 0;\">civil unrest;</li><li style=\"margin:2px 0;\">pandemics;</li><li style=\"margin:2px 0;\">utility failures;</li><li style=\"margin:2px 0;\">major technology failures; or</li><li style=\"margin:2px 0;\">other unforeseen events.</li></ul><p style=\"margin:6px 0;\">The affected Party shall notify the other Party as soon as reasonably practicable and resume performance once the event has ended.</p>"],
  ["CLIENT ACKNOWLEDGEMENTS", "<p style=\"margin:6px 0;\">The Client acknowledges that:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">they have reviewed and accepted the Quotation or Work Order before the Services commence;</li><li style=\"margin:2px 0;\">the selection of a suitable property remains the Client's decision;</li><li style=\"margin:2px 0;\">lease approval remains subject to the landlord's acceptance;</li><li style=\"margin:2px 0;\">rental prices and lease conditions may change during negotiations;</li><li style=\"margin:2px 0;\">independent legal, taxation and financial advice should be obtained before signing any lease agreement;</li><li style=\"margin:2px 0;\">some Services involve coordination with independent third parties; and</li><li style=\"margin:2px 0;\">they have had the opportunity to ask questions and obtain independent professional advice before entering into this Agreement.</li></ul>"],
  ["SUSPENSION & TERMINATION", "<p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">21.1 Suspension</p><p style=\"margin:6px 0;\">Seventh Sky may suspend the Services where:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">the Client fails to make payment in accordance with this Agreement;</li><li style=\"margin:2px 0;\">the Client fails to provide information or documentation reasonably required to perform the Services;</li><li style=\"margin:2px 0;\">the Client provides false or misleading information;</li><li style=\"margin:2px 0;\">the Client requests suspension; or</li><li style=\"margin:2px 0;\">continuation of the Services would be unlawful or impracticable.</li></ul><p style=\"margin:6px 0;\">Where practicable, Seventh Sky will notify the Client before suspending the Services.</p><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">21.2 Termination</p><p style=\"margin:6px 0;\">Either Party may terminate this Agreement by giving thirty (30) days' written notice, provided all completed Services and outstanding payments have been settled.</p><p style=\"margin:6px 0;\">Seventh Sky may terminate this Agreement immediately where the Client:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">commits a material breach of this Agreement;</li><li style=\"margin:2px 0;\">provides fraudulent or misleading information;</li><li style=\"margin:2px 0;\">fails to make payment after receiving written notice;</li><li style=\"margin:2px 0;\">engages in unlawful conduct; or</li><li style=\"margin:2px 0;\">prevents Seventh Sky from performing the agreed Services.</li></ul><p style=\"margin:6px 0;\">Where the Client terminates after Services have commenced, the Client remains responsible for payment for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Services already completed;</li><li style=\"margin:2px 0;\">property searches undertaken;</li><li style=\"margin:2px 0;\">inspections coordinated;</li><li style=\"margin:2px 0;\">negotiations conducted;</li><li style=\"margin:2px 0;\">approved third-party costs incurred; and</li><li style=\"margin:2px 0;\">other reasonable expenses incurred before termination.</li></ul><p style=\"margin:6px 0;\">Termination does not affect any rights or obligations that arose before the termination date.</p>"],
  ["NON-CIRCUMVENTION", "<p style=\"margin:6px 0;\">The Client acknowledges that Seventh Sky invests significant time, expertise and commercial resources in identifying suitable business premises and coordinating lease opportunities.</p><p style=\"margin:6px 0;\">Accordingly, where Seventh Sky introduces a property, landlord, property owner or authorised leasing representative to the Client, the Client agrees that, during the term of this Agreement and for twelve (12) months after the introduction, the Client will not intentionally bypass Seventh Sky to complete a lease transaction for the introduced property without Seventh Sky's prior written consent.</p><p style=\"margin:6px 0;\">Where a lease is completed for a property introduced by Seventh Sky during this period, the agreed service fees or success fees specified in the approved Quotation or Work Order remain payable.</p><p style=\"margin:6px 0;\">This clause does not prevent the Client from independently leasing properties that were not introduced by Seventh Sky.</p><p style=\"margin:6px 0;\">Note: I have retained a concise non-circumvention clause because, unlike most of your other direct-service agreements, this protection is commercially important for tenancy management and replaces the lengthy 2-page clause in Version 0.1.</p>"],
  ["GENERAL PROVISIONS", "<p style=\"margin:6px 0;\">Unless otherwise agreed in writing:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">this Agreement, together with the accepted Quotation, Work Order and Schedules, constitutes the entire agreement between the Parties;</li><li style=\"margin:2px 0;\">any amendment must be be made in writing and signed or electronically accepted by both Parties;</li><li style=\"margin:2px 0;\">failure by either Party to enforce any provision does not waive its rights;</li><li style=\"margin:2px 0;\">if any provision is held to be invalid or unenforceable, the remaining provisions remain in full force and effect; and</li><li style=\"margin:2px 0;\">notices under this Agreement may be delivered by hand, courier, registered post or email.</li></ul>"],
  ["GOVERNING LAW & DISPUTE RESOLUTION", "<p style=\"margin:6px 0;\">This Agreement shall be governed by the laws of the People's Republic of Bangladesh.</p><p style=\"margin:6px 0;\">The Parties agree to make reasonable efforts to resolve any dispute through good faith discussions before commencing legal proceedings.</p><p style=\"margin:6px 0;\">If the dispute cannot be resolved through negotiation, the Parties may agree to mediation or another recognised alternative dispute resolution process before referring the matter to the competent courts of Bangladesh.</p><p style=\"margin:6px 0;\">Nothing in this clause prevents either Party from seeking urgent legal or equitable relief where necessary.</p>"],
  ["EXECUTION", "<p style=\"margin:6px 0;\">By signing this Agreement, the Parties confirm that they:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">have read and understood this Agreement;</li><li style=\"margin:2px 0;\">have had the opportunity to obtain independent legal or professional advice;</li><li style=\"margin:2px 0;\">enter into this Agreement voluntarily; and</li><li style=\"margin:2px 0;\">agree to be legally bound by its terms.</li></ul><p style=\"margin:6px 0;\">This Agreement may be executed in counterparts and by electronic signature, including through approved digital signature platforms such as DocuSign. Each signed copy shall be deemed an original and together constitute one Agreement.</p>"],
];
